from pathlib import Path
p=Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s=p.read_text()
old='''{paymentStatus === "released" && <p className="wallet-success-note"><Check size={14} /> تم خصم نسبة المنصة وتحويل صافي المبلغ لمقدم الخدمة.</p>}<button className="wallet-settings-trigger"'''
new='''{paymentStatus === "released" && <><p className="wallet-success-note"><Check size={14} /> تم خصم نسبة المنصة وتحويل صافي المبلغ لمقدم الخدمة.</p>{!ratingSubmitted ? <div className="rating-card"><div className="rating-card-head"><div><span className="section-label">رأيك يهمنا</span><strong>كيف كانت تجربتك مع مقدم الخدمة؟</strong></div><Star size={19} /></div><div className="rating-stars" role="radiogroup" aria-label="تقييم الخدمة">{[1, 2, 3, 4, 5].map((score) => <button key={score} type="button" className={score <= ratingScore ? "selected" : ""} onClick={() => setRatingScore(score)} aria-label={`${score} نجوم`}><Star size={22} fill="currentColor" /></button>)}</div><textarea value={ratingComment} onChange={(event) => setRatingComment(event.target.value)} placeholder="أضف ملاحظة اختيارية عن جودة الخدمة..." /><button className="rating-submit" onClick={submitServiceRating} disabled={rateServiceMutation.isPending}>{rateServiceMutation.isPending ? "جارٍ إرسال التقييم..." : "إرسال التقييم"}</button></div> : <p className="rating-thanks"><Star size={15} fill="currentColor" /> تم حفظ تقييمك وإضافة نقاط الخبرة والأولوية لمقدم الخدمة.</p>}</>}<button className="wallet-settings-trigger"'''
if old not in s: raise SystemExit('rating insertion text not found')
p.write_text(s.replace(old,new,1))
